#include <stdio.h>
#define BAD(X) X*X
#define GOOD(X) ((X)*(X))
int square_once(int value);
int main(void) {
    int x = 4;
    printf("bad addition=%d\n", BAD(x+1));
    printf("bad division=%d\n", 36/BAD(3));
    printf("grouped=%d\n", GOOD(x+1));
    int counter = 3;
    printf("function=%d\n", square_once(++counter));
    printf("counter=%d\n", counter);
    /* BAD(++x) would expand to ++x*++x: undefined behavior. */
    return 0;
}
int square_once(int value) { return value * value; }

