#include <stdio.h>
#include <string.h>
#include "entry_api.h"
static int line(char *text, int capacity) {
    if (fgets(text, capacity, stdin) == NULL) return 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n' || ch == EOF) return !ferror(stdin);
    while (ch != '\n' && ch != EOF) ch = getchar();
    return 0;
}
int read_entry(Entry *person) {
    return line(person->first, ENTRY_CAPACITY) && line(person->last, ENTRY_CAPACITY);
}
void print_entry(const Entry *person) {
    printf("name=%s %s\n", person->first, person->last);
}

