#include <stdio.h>
#include <math.h>
struct rectangular { double x; double y; };
struct polar { double radius; double degrees; };
struct polar convert(struct rectangular point);
int main(void) {
    struct rectangular point;
    if (scanf("%lf %lf", &point.x, &point.y) != 2 ||
        !isfinite(point.x) || !isfinite(point.y) || fabs(point.x) > 1e6 || fabs(point.y) > 1e6) return 1;
    struct polar answer = convert(point);
    printf("r=%.2f angle=%.2f\n", answer.radius, answer.degrees);
    return 0;
}
struct polar convert(struct rectangular point) {
    struct polar result;
    result.radius = hypot(point.x, point.y);
    result.degrees = result.radius == 0.0 ? 0.0 : atan2(point.y, point.x) * 180.0 / acos(-1.0);
    return result;
}

#include <stdio.h>
