#define ROOT(X) _Generic((X), float:sqrtf, long double:sqrtl, default:sqrt)(X)
#define DEGREE_SINE(X) _Generic((X), \
    float:sinf((X) * acosf(-1.0f) / 180.0f), \
    long double:sinl((X) * acosl(-1.0L) / 180.0L), \
    default:sin((X) * acos(-1.0) / 180.0))
int main(void) {
    float small = 2.0f;
    double regular = 2.0;
    long double wide = 2.0L;
    printf("float=%.18Lf\n", (long double)ROOT(small));
    printf("double=%.18Lf\n", (long double)ROOT(regular));
    printf("long double=%.18Lf\n", ROOT(wide));
    printf("sine=%.3Lf\n", DEGREE_SINE(30.0L));
    return 0;
}

