#include <stdio.h>
#include <stdlib.h>
#define COUNT 40
void fill(double *values, size_t count);
void show(const double *values, size_t count);
int ascending(const void *left, const void *right);
int main(void) {
    double values[COUNT];
    fill(values, COUNT);
    puts("BEFORE");
    show(values, COUNT);
    qsort(values, COUNT, sizeof values[0], ascending);
    puts("AFTER");
    show(values, COUNT);
    return 0;
}
void fill(double *values, size_t count) {
    for (size_t i = 0; i < count; i++) values[i] = (double)(rand() % 1000) / 8.0;
}
void show(const double *values, size_t count) {
    for (size_t i = 0; i < count; i++) {
        printf("%.3f", values[i]);
        putchar(i % 8 == 7 || i + 1 == count ? '\n' : ' ');
    }
}
int ascending(const void *left, const void *right) {
    const double *a = left;
    const double *b = right;
    return (*a > *b) - (*a < *b);
}

